import sys

def main():
    data = sys.stdin.read().split()
    n, m, k = int(data[0]), int(data[1]), int(data[2])
    b = list(map(int, data[3:3 + n]))
    if m * k > n:
        print(-1)
        return
    def ok(d):
        cnt = run = 0
        for x in b:
            if x <= d:
                run += 1
                if run == k:
                    cnt += 1
                    run = 0
            else:
                run = 0
        return cnt >= m
    lo, hi = min(b), max(b)
    while lo < hi:
        mid = (lo + hi) // 2
        if ok(mid):
            hi = mid
        else:
            lo = mid + 1
    print(lo)

